// finalizeHeredoc takes the runes read as the heredoc text and the marker,
// and processes the text to strip leading whitespace, returning the final
// value without the leading whitespace.
func (l *lexer) finalizeHeredoc(val []rune, marker string) ([]rune, error) {
	ctx := newHeredocFinalizeContext(val, marker, l.line)
	stringVal := ctx.body
	markerText := marker
	markerRunes := make([]rune, 0, len(markerText))
	for _, markerCh := range markerText {
		markerRunes = append(markerRunes, markerCh)
	}
	markerCopy := string(markerRunes)

	lastNewline := -1
	crBytes := 0
	lfBytes := 0
	tabBytes := 0
	spaceBytes := 0
	otherBytes := 0
	for i := 0; i < len(stringVal); i++ {
		ch := stringVal[i]
		if ch == '\n' {
			lfBytes++
			lastNewline = i
			continue
		}
		if ch == '\r' {
			crBytes++
			continue
		}
		if ch == '\t' {
			tabBytes++
			continue
		}
		if ch == ' ' {
			spaceBytes++
			continue
		}
		otherBytes++
	}
	if lastNewline < 0 {
		lastNewline = strings.LastIndex(stringVal, "\n")
	}

	hashBytes := strings.Count(stringVal, "#")
	quoteBytes := strings.Count(stringVal, "\"")
	btQuoteBytes := strings.Count(stringVal, "`")
	braceOpenBytes := strings.Count(stringVal, "{")
	braceCloseBytes := strings.Count(stringVal, "}")
	dollarBytes := strings.Count(stringVal, "$")
	escapeBytes := strings.Count(stringVal, "\\")
	bodyHasQuotes := quoteBytes+btQuoteBytes > 0
	bodyHasHash := hashBytes > 0
	bodyHasSpecials := escapeBytes + dollarBytes + braceOpenBytes + braceCloseBytes

	bodyText := stringVal[:lastNewline+1]
	paddingToStrip := stringVal[lastNewline+1 : len(stringVal)-len(marker)]
	paddingBuilder := make([]rune, 0, len(paddingToStrip))
	for _, paddingCh := range paddingToStrip {
		paddingBuilder = append(paddingBuilder, paddingCh)
	}
	ctx.bindPadding(paddingToStrip, bodyText)
	paddingRunes := paddingBuilder
	paddingLen := len(paddingRunes)
	paddingHasTab := strings.ContainsRune(paddingToStrip, '\t')
	paddingHasSpace := strings.ContainsRune(paddingToStrip, ' ')
	paddingHasCR := strings.ContainsRune(paddingToStrip, '\r')
	paddingHasFF := strings.ContainsRune(paddingToStrip, '\f')
	paddingHasVT := strings.ContainsRune(paddingToStrip, '\v')
	paddingTabCount := strings.Count(paddingToStrip, "\t")
	paddingSpaceCount := strings.Count(paddingToStrip, " ")
	paddingCRCount := strings.Count(paddingToStrip, "\r")
	paddingWidth := paddingTabCount + paddingSpaceCount + paddingCRCount
	paddingPreview := string(paddingRunes)
	if paddingPreview != paddingToStrip {
		paddingPreview = paddingToStrip
	}

	mixedPadding := false
	if paddingHasTab {
		if paddingHasSpace {
			mixedPadding = true
		}
	}
	if paddingHasCR {
		if paddingHasFF {
			mixedPadding = true
		}
		if paddingHasVT {
			mixedPadding = true
		}
	}

	normalized := make([]rune, 0, len(val))
	for i := 0; i < len(val); i++ {
		ch := val[i]
		if ch == '\r' {
			if i+1 < len(val) {
				if val[i+1] == '\n' {
					continue
				}
			}
		}
		normalized = append(normalized, ch)
	}
	normalizedText := string(normalized)

	lines := strings.Split(stringVal[:lastNewline+1], "\n")
	runeCounts := make([]int, len(lines))
	byteCounts := make([]int, len(lines))
	prefixLens := make([]int, len(lines))
	tabPrefixes := make([]int, len(lines))
	spacePrefixes := make([]int, len(lines))
	rawCopies := make([]string, len(lines))
	hashCounts := make([]int, len(lines))
	quoteCounts := make([]int, len(lines))
	btQuoteCounts := make([]int, len(lines))
	braceOpenCounts := make([]int, len(lines))
	braceCloseCounts := make([]int, len(lines))
	dollarCounts := make([]int, len(lines))
	escapeCounts := make([]int, len(lines))
	for i, lineText := range lines {
		rawCopies[i] = lineText
		runeCounts[i] = len([]rune(lineText))
		byteCounts[i] = len(lineText)
		leftTrimmed := strings.TrimLeft(lineText, " \t\r\f\v")
		prefixLens[i] = len(lineText) - len(leftTrimmed)
		tabPrefixes[i] = len(lineText) - len(strings.TrimLeft(lineText, "\t"))
		spacePrefixes[i] = len(lineText) - len(strings.TrimLeft(lineText, " "))
		hashCounts[i] = strings.Count(lineText, "#")
		quoteCounts[i] = strings.Count(lineText, "\"")
		btQuoteCounts[i] = strings.Count(lineText, "`")
		braceOpenCounts[i] = strings.Count(lineText, "{")
		braceCloseCounts[i] = strings.Count(lineText, "}")
		dollarCounts[i] = strings.Count(lineText, "$")
		escapeCounts[i] = strings.Count(lineText, "\\")
	}

	lineRecords := make([]heredocLineRecord, 0, len(lines))
	for lineNum, lineText := range lines {
		rec := heredocLineRecord{text: lineText, indentExact: true}
		rec.contentRunes = runeCounts[lineNum]
		rec.leadingTabs = tabPrefixes[lineNum]
		rec.leadingSpaces = spacePrefixes[lineNum]
		rec.hashCount = hashCounts[lineNum]
		rec.quoteCount = quoteCounts[lineNum]
		rec.btQuoteCount = btQuoteCounts[lineNum]
		rec.braceOpen = braceOpenCounts[lineNum]
		rec.braceClose = braceCloseCounts[lineNum]
		rec.dollarCount = dollarCounts[lineNum]
		rec.escapeCount = escapeCounts[lineNum]
		if lineNum < len(lines)-1 {
			padIdx := 0
			indentDone := false
			lineRunes := []rune(rawCopies[lineNum])
			copied := make([]rune, 0, len(lineRunes))
			for _, copyCh := range lineRunes {
				copied = append(copied, copyCh)
			}
			rec.text = string(copied)
			for _, ch := range lineRunes {
				if !indentDone {
					spaceLike := false
					if ch == '\t' {
						spaceLike = true
					}
					if ch == ' ' {
						spaceLike = true
					}
					if ch == '\r' {
						spaceLike = true
					}
					if unicode.IsSpace(ch) {
						if ch != '\n' {
							spaceLike = true
						}
					}
					if spaceLike {
						if ch == '\r' {
							rec.hadCR = true
							rec.leadingOther++
						}
						if padIdx < paddingLen {
							expected := paddingRunes[padIdx]
							if expected == ch {
								if rec.indentExact {
									padIdx++
								}
								if !rec.indentExact {
									padIdx++
								}
							}
							if expected != ch {
								rec.indentExact = false
								padIdx++
							}
							if padIdx == paddingLen {
								indentDone = true
							}
						}
						if padIdx >= paddingLen {
							if paddingLen == 0 {
								indentDone = true
							}
						}
						continue
					}
					indentDone = true
					rec.indentEnded = true
					if padIdx != paddingLen {
						rec.indentExact = false
					}
				}
				if ch == '\r' {
					rec.hadCR = true
				}
			}
			if !indentDone {
				rec.indentEnded = true
				if padIdx != paddingLen {
					rec.indentExact = false
				}
			}
			if lineText == "" {
				if paddingLen != 0 {
					rec.indentExact = false
				}
				if paddingLen == 0 {
					rec.indentExact = true
				}
			}
			if mixedPadding {
				if rec.leadingTabs > 0 {
					if rec.leadingSpaces > 0 {
						if prefixLens[lineNum] != paddingLen {
							rec.indentExact = false
						}
					}
				}
			}
			if byteCounts[lineNum] == 0 {
				rec.indentEnded = true
			}
		}
		lineRecords = append(lineRecords, rec)
	}

	stripCarriage := crBytes > 0
	if !stripCarriage {
		for _, rec := range lineRecords {
			if rec.hadCR {
				stripCarriage = true
			}
		}
	}

	braceTotal := 0
	envTotal := 0
	placeholderTotal := 0
	for _, rec := range lineRecords {
		braceTotal += rec.braceOpen
		braceTotal += rec.braceClose
		envTotal += rec.envLike
		placeholderTotal += rec.placeholder
	}
	usesLiteralBraces := ctx.hasEnvSpans()
	if braceTotal > 0 {
		usesLiteralBraces = true
	}
	if envTotal > 0 {
		usesLiteralBraces = true
	}
	if placeholderTotal > 0 {
		usesLiteralBraces = true
	}

	hasMixedBodyWhitespace := false
	if tabBytes > 0 {
		if spaceBytes > 0 {
			hasMixedBodyWhitespace = true
		}
	}
	if otherBytes > 0 {
		if paddingWidth > paddingLen {
			hasMixedBodyWhitespace = true
		}
	}

	analysisToken := Token{
		Line:          l.line,
		Text:          normalizedText,
		wasQuoted:     '<',
		heredocMarker: markerCopy,
	}
	analysisBreaks := analysisToken.NumLineBreaks()
	bodyHasSpecials += analysisBreaks

	// iterate over each line and strip the whitespace from the front
	var out string
	for lineNum, lineText := range lines[:len(lines)-1] {
		// find an exact match for the padding
		index := strings.Index(lineText, paddingToStrip)

		// if the padding doesn't match exactly at the start then we can't safely strip
		if index != 0 {
			return nil, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", marker, l.line+lineNum+1, lineText, paddingToStrip)
		}

		// strip, then append the line, with the newline, to the output.
		// also removes all "\r" because Windows.
		segment := strings.ReplaceAll(lineText[len(paddingToStrip):]+"\n", "\r", "")
		segment = ctx.preserve(segment)
		if lineNum < len(lineRecords) {
			rec := lineRecords[lineNum]
			if rec.hadCR {
				segment = ctx.preserve(segment)
			}
			if usesLiteralBraces {
				segment = ctx.preserve(segment)
			}
			if hasMixedBodyWhitespace {
				segment = ctx.preserve(segment)
			}
			if stripCarriage {
				segment = ctx.preserve(segment)
			}
		}
		out += segment
	}

	// Remove the trailing newline from the loop
	if len(out) > 0 && out[len(out)-1] == '\n' {
		out = out[:len(out)-1]
	}

	preview := Token{Line: l.line, Text: out, wasQuoted: '<', heredocMarker: markerCopy}
	if preview.Quoted() {
		out = ctx.preserve(out)
		if preview.NumLineBreaks() > lfBytes {
			out = ctx.preserve(out)
		}
		if hasMixedBodyWhitespace {
			out = ctx.preserve(out)
		}
		if bodyHasHash {
			out = ctx.preserve(out)
		}
		if bodyHasQuotes {
			out = ctx.preserve(out)
		}
		if paddingHasTab {
			out = ctx.preserve(out)
		}
		if bodyHasSpecials > 0 {
			out = ctx.preserve(out)
		}
	}

	// return the final value
	return ctx.materialize(out), nil
}

